        n = len(intervals)
        best = (-1, ())
        def rec(start, k, chosen, score):
            nonlocal best
            cand = (score, tuple(chosen))
            if cand > best:
                best = cand
            if k == 4:
                return
            for i in range(start, n):
                if all(intervals[i][0] > intervals[j][1] or intervals[i][1] < intervals[j][0] for j in chosen):
                    chosen.append(i)
                    rec(i + 1, k + 1, chosen, score + intervals[i][2])
                    chosen.pop()
        rec(0, 0, [], 0)
        return list(best[1])

