    vector<int> best;
    long long bestScore = -1;
    void rec(vector<vector<int>>& iv, int start, int k, vector<int>& chosen, long long score) {
        if (score > bestScore || (score == bestScore && chosen < best)) {
            bestScore = score;
            best = chosen;
        }
        if (k == 4) return;
        int n = iv.size();
        for (int i = start; i < n; i++) {
            bool ok = true;
            for (int j : chosen)
                if (!(iv[i][0] > iv[j][1] || iv[i][1] < iv[j][0])) { ok = false; break; }
            if (!ok) continue;
            chosen.push_back(i);
            rec(iv, i + 1, k + 1, chosen, score + iv[i][2]);
            chosen.pop_back();
        }
    }
    vector<int> maximumWeight(vector<vector<int>>& intervals) {
        vector<int> chosen;
        rec(intervals, 0, 0, chosen, 0);
