class Solution {
    private List<Integer> best = new ArrayList<>();
    private long bestScore = -1;
    private int[][] iv;
    private void rec(int start, int k, List<Integer> chosen, long score) {
        boolean better = score > bestScore;
        if (!better && score == bestScore) {
            for (int t = 0; t < Math.min(chosen.size(), best.size()) && !better; t++) {
                if (!chosen.get(t).equals(best.get(t))) better = chosen.get(t) < best.get(t);
            }
            if (!better && chosen.size() != best.size() && chosen.size() < best.size()
                    && chosen.equals(best.subList(0, chosen.size()))) better = true;
        }
        if (better) { bestScore = score; best = new ArrayList<>(chosen); }
        if (k == 4) return;
        for (int i = start; i < iv.length; i++) {
            boolean ok = true;
            for (int j : chosen)
                if (!(iv[i][0] > iv[j][1] || iv[i][1] < iv[j][0])) { ok = false; break; }
            if (!ok) continue;
            chosen.add(i);
            rec(i + 1, k + 1, chosen, score + iv[i][2]);
            chosen.remove(chosen.size() - 1);
        }
    }
    public List<Integer> maximumWeight(int[][] intervals) {
        this.iv = intervals;
        rec(0, 0, new ArrayList<>(), 0);
        return best;
    }
}

