from bisect import bisect_right
class Solution:
    def maximumWeight(self, intervals):
        n = len(intervals)
        order = sorted(range(n), key=lambda i: intervals[i][0])
        starts = [intervals[i][0] for i in order]
        nxt = [bisect_right(starts, intervals[i][1]) for i in order]
        dp = [[(0, ()) for _ in range(n + 1)] for _ in range(5)]
        for j in range(1, 5):
            for i in range(n - 1, -1, -1):
                idx = order[i]
                cur = dp[j][i + 1]
                s2, lst2 = dp[j - 1][nxt[i]]
                cand = (s2 + intervals[idx][2], tuple(sorted(lst2 + (idx,))))
                if cand[0] > cur[0] or (cand[0] == cur[0] and cand[1] < cur[1]):
                    cur = cand
                dp[j][i] = cur
        return list(dp[4][0][1])

