class Solution {
public:
    vector<int> maximumWeight(vector<vector<int>>& intervals) {
        int n = intervals.size();
        vector<int> order(n);
        iota(order.begin(), order.end(), 0);
        sort(order.begin(), order.end(), [&](int a, int b){ return intervals[a][0] < intervals[b][0]; });
        vector<long long> starts(n);
        for (int i = 0; i < n; i++) starts[i] = intervals[order[i]][0];
        vector<int> nxt(n);
        for (int i = 0; i < n; i++)
            nxt[i] = upper_bound(starts.begin(), starts.end(), (long long)intervals[order[i]][1]) - starts.begin();
        using Cell = pair<long long, vector<int>>;
        vector<vector<Cell>> dp(5, vector<Cell>(n + 1, {0LL, {}}));
        for (int j = 1; j <= 4; j++) {
            for (int i = n - 1; i >= 0; i--) {
                int idx = order[i];
                Cell cur = dp[j][i + 1];
                auto [s2, lst2] = dp[j - 1][nxt[i]];
                vector<int> merged = lst2;
                merged.push_back(idx);
                sort(merged.begin(), merged.end());
                Cell cand{s2 + intervals[idx][2], merged};
                if (cand.first > cur.first || (cand.first == cur.first && cand.second < cur.second))
                    cur = cand;
                dp[j][i] = cur;
            }
        }
        return dp[4][0].second;
    }
};

