class Solution {
    public List<Integer> maximumWeight(int[][] intervals) {
        int n = intervals.length;
        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) order[i] = i;
        Arrays.sort(order, (a, b) -> Integer.compare(intervals[a][0], intervals[b][0]));
        long[] starts = new long[n];
        for (int i = 0; i < n; i++) starts[i] = intervals[order[i]][0];
        int[] nxt = new int[n];
        for (int i = 0; i < n; i++) {
            int lo = 0, hi = n;
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (starts[mid] <= intervals[order[i]][1]) lo = mid + 1; else hi = mid;
            }
            nxt[i] = lo;
        }
        long[][] score = new long[5][n + 1];
        List<List<List<Integer>>> list = new ArrayList<>();
        for (int j = 0; j <= 4; j++) {
            list.add(new ArrayList<>());
            for (int i = 0; i <= n; i++) list.get(j).add(new ArrayList<>());
        }
        for (int j = 1; j <= 4; j++) {
            for (int i = n - 1; i >= 0; i--) {
                int idx = order[i];
                long sc = score[j][i + 1];
                List<Integer> ls = list.get(j).get(i + 1);
                long s2 = score[j - 1][nxt[i]] + intervals[idx][2];
                List<Integer> l2 = new ArrayList<>(list.get(j - 1).get(nxt[i]));
                l2.add(idx);
                Collections.sort(l2);
                boolean take = s2 > sc || (s2 == sc && cmp(l2, ls) < 0);
                score[j][i] = take ? s2 : sc;
                list.get(j).set(i, take ? l2 : ls);
            }
        }
        return list.get(4).get(0);
    }
    private int cmp(List<Integer> a, List<Integer> b) {
        for (int t = 0; t < Math.min(a.size(), b.size()); t++) {
            int d = a.get(t) - b.get(t);
            if (d != 0) return d;
        }
        return a.size() - b.size();
    }
}

