            if (a[t] !== b[t]) return a[t] - b[t];
        return a.length - b.length;
    };
    const score = Array.from({length: 5}, () => new Array(n + 1).fill(0));
    const list = Array.from({length: 5}, () => Array.from({length: n + 1}, () => []));
